//! Parity with `runtime/home_path_text.py` over a recorded corpus.
//!
//! The fixture is generated by `scripts/ci/generate_home_path_text_parity.py`,
//! which runs the module's two functions with `pathlib` and `os.path` read as
//! POSIX and as Windows, so both platforms' answers come from real Python on
//! whatever host records them. The `Rust workspace` CI job builds this crate
//! only on `ubuntu-latest`, so the Windows replay below is the only place the
//! `#[cfg(windows)]` spelling is exercised at all.

use std::path::PathBuf;

use serde_json::Value;

use crate::home_path_text::{
    expand_home, expand_home_nt, expand_home_posix, normalize_path, normpath_nt, normpath_posix,
};

const PARITY: &str = include_str!("../../../../tests/fixtures/home-path-text-parity.v1.json");

fn corpus() -> Value {
    let document: Value = serde_json::from_str(PARITY).expect("parity fixture parses");
    assert_eq!(
        document["schema"], "home-path-text-parity.v1",
        "fixture schema moved"
    );
    document
}

fn text<'a>(case: &'a Value, field: &str) -> &'a str {
    case.get(field)
        .and_then(Value::as_str)
        .unwrap_or_else(|| panic!("case is missing {field}"))
}

fn cases<'a>(document: &'a Value, flavour: &str, group: &str) -> &'a [Value] {
    document[flavour][group]
        .as_array()
        .map(Vec::as_slice)
        .unwrap_or_else(|| panic!("fixture lists no {flavour} {group} cases"))
}

#[test]
fn expand_home_matches_python_on_posix() {
    let document = corpus();
    let recorded = cases(&document, "posix", "expand_home");
    assert!(recorded.len() >= 100, "fixture thinned out");
    for case in recorded {
        let home = text(case, "home");
        let value = text(case, "value");
        assert_eq!(
            expand_home_posix(value, home),
            text(case, "expected"),
            "posix expand_home({value:?}, {home:?})"
        );
    }
}

#[test]
fn expand_home_matches_python_on_windows() {
    let document = corpus();
    let recorded = cases(&document, "windows", "expand_home");
    assert!(recorded.len() >= 100, "fixture thinned out");
    for case in recorded {
        let home = text(case, "home");
        let value = text(case, "value");
        assert_eq!(
            expand_home_nt(value, home),
            text(case, "expected"),
            "windows expand_home({value:?}, {home:?})"
        );
    }
}

#[test]
fn normpath_matches_python_on_both_platforms() {
    let document = corpus();
    for case in cases(&document, "posix", "normpath") {
        let value = text(case, "value");
        assert_eq!(
            normpath_posix(value),
            text(case, "expected"),
            "posix normpath({value:?})"
        );
    }
    for case in cases(&document, "windows", "normpath") {
        let value = text(case, "value");
        assert_eq!(
            normpath_nt(value),
            text(case, "expected"),
            "windows normpath({value:?})"
        );
    }
}

/// A relative path whose components all collapse is `.`, never the empty
/// string: callers refuse `.` by name, and an empty string slips past them.
#[test]
fn a_collapsing_relative_path_is_the_current_directory() {
    let document = corpus();
    let collapsing = cases(&document, "posix", "normpath")
        .iter()
        .filter(|case| text(case, "expected") == ".")
        .count();
    assert!(collapsing >= 5, "fixture stopped recording the shape");
    assert_eq!(normpath_posix("a/.."), ".");
    assert_eq!(normpath_posix("./."), ".");
    assert_eq!(normalize_path(".", None), ".");
}

/// The public entry points answer this platform's own recorded section.
#[test]
fn the_public_helpers_answer_for_this_platform() {
    let document = corpus();
    #[cfg(windows)]
    let flavour = "windows";
    #[cfg(not(windows))]
    let flavour = "posix";
    for case in cases(&document, flavour, "expand_home") {
        let home = PathBuf::from(text(case, "home"));
        let value = text(case, "value");
        assert_eq!(
            expand_home(value, Some(&home)),
            text(case, "expected"),
            "{flavour} expand_home({value:?})"
        );
    }
    for case in cases(&document, flavour, "normpath") {
        let value = text(case, "value");
        assert_eq!(
            normalize_path(value, None),
            text(case, "expected"),
            "{flavour} normalize_path({value:?})"
        );
    }
}
